import http from 'node:http';
import { readFile, mkdir, writeFile, rename } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';

const root = path.dirname(fileURLToPath(import.meta.url));
const publicDir = path.join(root, 'public');
const defaultDataFile = path.join(root, 'data', 'books.json');
const assets = {
  '/': ['index.html', 'text/html; charset=utf-8'],
  '/styles.css': ['styles.css', 'text/css; charset=utf-8'],
  '/app.js': ['app.js', 'text/javascript; charset=utf-8'],
};

function send(res, status, value) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(value));
}

async function bodyOf(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 100_000) {
      const error = new Error('Request is too large.');
      error.status = 413;
      throw error;
    }
  }
  try { return JSON.parse(body); }
  catch {
    const error = new Error('Invalid JSON.');
    error.status = 400;
    throw error;
  }
}

export function createApp({ dataFile = defaultDataFile } = {}) {
  // Serialize mutations so concurrent requests never overwrite each other's changes.
  let pending = Promise.resolve();
  async function load() {
    try {
      const books = JSON.parse(await readFile(dataFile, 'utf8'));
      if (!Array.isArray(books)) throw new Error('Books file must contain an array.');
      return books;
    } catch (error) {
      if (error.code === 'ENOENT') return [];
      throw error;
    }
  }
  function mutate(fn) {
    const operation = pending.then(async () => {
      const books = await load();
      const result = fn(books);
      if (!result) return null;
      await mkdir(path.dirname(dataFile), { recursive: true });
      const temp = `${dataFile}.${randomUUID()}.tmp`;
      await writeFile(temp, JSON.stringify(books, null, 2) + '\n');
      await rename(temp, dataFile);
      return result;
    });
    pending = operation.catch(() => {});
    return operation;
  }

  return async (req, res) => {
    try {
      const pathname = new URL(req.url, 'http://localhost').pathname;
      if (pathname === '/api/books' && req.method === 'GET') {
        return send(res, 200, await load());
      }
      if (pathname === '/api/books' && req.method === 'POST') {
        const input = await bodyOf(req);
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        const author = typeof input?.author === 'string' ? input.author.trim() : '';
        const notes = typeof input?.notes === 'string' ? input.notes.trim() : '';
        if (!title || !author || title.length > 200 || author.length > 200 || notes.length > 10000) {
          return send(res, 400, { error: 'Enter a title and author (up to 200 characters each) and notes under 10,000 characters.' });
        }
        const book = await mutate(books => {
          const created = { id: randomUUID(), title, author, notes, status: 'reading', addedAt: new Date().toISOString(), finishedAt: null };
          books.push(created);
          return created;
        });
        return send(res, 201, book);
      }
      const match = pathname.match(/^\/api\/books\/([a-f\d-]{36})$/i);
      if (match && req.method === 'GET') {
        const book = (await load()).find(item => item.id === match[1]);
        return book ? send(res, 200, book) : send(res, 404, { error: 'Book not found.' });
      }
      if (match && req.method === 'PATCH') {
        const input = await bodyOf(req);
        if (input?.status !== 'finished') return send(res, 400, { error: 'Only marking a book finished is supported.' });
        const book = await mutate(books => {
          const found = books.find(item => item.id === match[1]);
          if (!found) return null;
          if (found.status !== 'finished') {
            found.status = 'finished';
            found.finishedAt = new Date().toISOString();
          }
          return found;
        });
        return book ? send(res, 200, book) : send(res, 404, { error: 'Book not found.' });
      }
      if (pathname.startsWith('/api/')) return send(res, 404, { error: 'Not found.' });
      const asset = assets[pathname] || (req.method === 'GET' && /^\/books\/[a-f\d-]{36}$/i.test(pathname) ? assets['/'] : null);
      if (req.method !== 'GET' || !asset) return send(res, 404, { error: 'Not found.' });
      const [filename, type] = asset;
      res.writeHead(200, { 'Content-Type': type });
      res.end(await readFile(path.join(publicDir, filename)));
    } catch (error) {
      if (error.status) return send(res, error.status, { error: error.message });
      console.error(error);
      send(res, 500, { error: 'Something went wrong while accessing your books.' });
    }
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT || 3000);
  http.createServer(createApp()).listen(port, () => console.log(`Reading Room is ready at http://localhost:${port}`));
}

