const app = document.querySelector('#app');
let books = [];
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const dateText = value => value ? new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : '';

async function request(url, options) {
  const response = await fetch(url, options);
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Something went wrong.');
  return result;
}
function notice(message) {
  const toast = document.querySelector('#toast');
  if (!toast) return;
  toast.textContent = message;
  toast.hidden = false;
  clearTimeout(notice.timer);
  notice.timer = setTimeout(() => toast.hidden = true, 4000);
}
function navigate(path) {
  history.pushState({}, '', path);
  render();
  window.scrollTo(0, 0);
}
const icons = {
  arrow: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg>',
  book: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M12 6c-3.3-2.2-7-2-10-1v14c3-.8 7-.9 10 1 3-1.9 7-1.8 10-1V5c-3-1-6.7-1.2-10 1Zm0 0v14"/></svg>',
  check: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>',
  plus: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>',
  link: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M10 13a5 5 0 0 0 7 .1l2-2a5 5 0 0 0-7-7l-1.2 1.2M14 11a5 5 0 0 0-7-.1l-2 2a5 5 0 0 0 7 7l1.2-1.2"/></svg>',
};
const toast = '<div id="toast" class="toast" role="status" hidden></div>';
function card(book, index) {
  const finished = book.status === 'finished';
  return `<article class="book-card">
    <a class="book-card-link" href="/books/${book.id}" data-link aria-label="View ${escapeHTML(book.title)}">
      <div class="book-cover cover-${index % 5}"><span class="cover-top">READING ROOM · ${finished ? 'FINISHED' : 'CURRENTLY READING'}</span><span class="cover-center">${escapeHTML(book.title)}</span><span class="cover-bottom">${escapeHTML(book.author)}</span></div>
      <div class="card-copy"><div class="card-heading"><h3>${escapeHTML(book.title)}</h3><span class="card-arrow">${icons.arrow}</span></div><p>by ${escapeHTML(book.author)}</p><span class="card-meta">${finished ? `Finished ${dateText(book.finishedAt)}` : 'On your nightstand'}</span></div>
    </a>
  </article>`;
}
function section(label, title, items, finished) {
  return `<section class="shelf"><div class="section-heading"><div><span class="eyebrow">${label} <span class="count">${String(items.length).padStart(2, '0')}</span></span><h2>${title}</h2></div><span class="section-decoration" aria-hidden="true">${finished ? '02' : '01'} / YOUR LIBRARY</span></div>
    ${items.length ? `<div class="book-grid">${items.map((book, i) => card(book, i + (finished ? 2 : 0))).join('')}</div>` : `<div class="empty-shelf"><span class="empty-icon">${icons.book}</span><div><h3>${finished ? 'A blank page, for now.' : 'Your shelf is waiting.'}</h3><p>${finished ? 'Books you finish will find a home here.' : 'Add your first book to begin your reading story.'}</p></div>${finished ? '' : '<button class="text-button" type="button" data-open-form>Add a book ' + icons.arrow + '</button>'}</div>`}
  </section>`;
}
function home() {
  const reading = books.filter(book => book.status !== 'finished').reverse();
  const finished = books.filter(book => book.status === 'finished').reverse();
  app.innerHTML = `<div class="hero"><div class="hero-content"><span class="eyebrow hero-eyebrow"><span class="asterisk">✳</span> THE PERSONAL BOOKSHELF</span><h1>A home for<br>your <em>reading.</em></h1><p>Keep the stories close. Track what you're reading, remember what you loved, and make room for what comes next.</p><button class="primary-button" type="button" data-open-form>${icons.plus}<span>Add a book</span></button></div><div class="hero-art" aria-hidden="true"><div class="art-circle"></div><div class="art-book art-back"><span>THE STORIES<br>WE KEEP</span><small>READING ROOM</small></div><div class="art-book art-front"><span>A LITTLE<br>MORE<br>EVERY DAY<span class="art-star">✳</span></span><small>VOL. 01 &nbsp; / &nbsp; YOUR LIBRARY</small></div><span class="art-caption">A collection in progress <span>↗</span></span></div></div>
    <div class="library-intro"><div><span class="eyebrow">YOUR LIBRARY</span><h2>Every book has a place.</h2></div><p>${books.length ? `${books.length} ${books.length === 1 ? 'book' : 'books'} on your shelf · ${reading.length} in progress · ${finished.length} finished` : 'Start with one. See where it takes you.'}</p></div>
    ${section('IN PROGRESS', 'Currently reading', reading, false)}${section('THE ARCHIVE', 'Finished books', finished, true)}
    <div class="bottom-cta"><div><span class="eyebrow">KEEP THE PAGES TURNING</span><h2>What’s next on your shelf?</h2></div><button class="outline-button" type="button" data-open-form>Add another book ${icons.arrow}</button></div>${formMarkup()}${toast}`;
  bindHome();
}
function formMarkup() {
  return `<dialog id="add-dialog" class="add-dialog"><div class="dialog-head"><div><span class="eyebrow">A NEW CHAPTER</span><h2>Add a book</h2></div><button class="close-button" type="button" data-close aria-label="Close">×</button></div><p class="dialog-intro">Give this one a spot on your shelf. You can jot down your thoughts, too.</p><form id="add-form"><label for="title">BOOK TITLE <span>*</span></label><input id="title" name="title" maxlength="200" required placeholder="e.g. The Creative Act" autofocus><label for="author">AUTHOR <span>*</span></label><input id="author" name="author" maxlength="200" required placeholder="e.g. Rick Rubin"><label for="notes">YOUR NOTES <span class="optional">OPTIONAL</span></label><textarea id="notes" name="notes" maxlength="10000" rows="4" placeholder="A thought, a quote, or why you picked it up..."></textarea><p id="form-error" class="form-error" role="alert" hidden></p><button class="primary-button form-submit" type="submit">Add to my shelf ${icons.arrow}</button></form></dialog>`;
}
function bindHome() {
  const dialog = document.querySelector('#add-dialog');
  document.querySelectorAll('[data-open-form]').forEach(button => button.addEventListener('click', () => dialog.showModal()));
  dialog.querySelector('[data-close]').addEventListener('click', () => dialog.close());
  dialog.addEventListener('click', event => { if (event.target === dialog) dialog.close(); });
  document.querySelector('#add-form').addEventListener('submit', async event => {
    event.preventDefault();
    const form = event.currentTarget;
    const button = form.querySelector('[type="submit"]');
    const error = form.querySelector('#form-error');
    button.disabled = true;
    error.hidden = true;
    try {
      const book = await request('/api/books', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.fromEntries(new FormData(form))) });
      books.push(book);
      dialog.close();
      home();
      notice('Added to your shelf.');
    } catch (cause) {
      error.textContent = cause.message;
      error.hidden = false;
    } finally { button.disabled = false; }
  });
}
async function detail(id) {
  app.innerHTML = '<div class="loading">Opening your book…</div>';
  try {
    const book = await request(`/api/books/${id}`);
