    document.querySelector('#finish-button')?.addEventListener('click', async event => {
      const button = event.currentTarget;
      button.disabled = true;
      try {
        const updated = await request(`/api/books/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'finished' }) });
        books = books.map(item => item.id === id ? updated : item);
        await detail(id);
        notice('Moved to your finished shelf.');
      } catch (cause) { button.disabled = false; notice(cause.message); }
    });
    document.querySelector('#share-button').addEventListener('click', async () => {
      try { await navigator.clipboard.writeText(window.location.href); notice('Book link copied to clipboard.'); }
      catch { notice(`Copy this link: ${window.location.href}`); }
    });
  } catch (error) {
    document.title = 'Book not found · Reading Room';
    app.innerHTML = `<div class="not-found"><span class="eyebrow">PAGE NOT FOUND</span><h1>This book isn’t on the shelf.</h1><p>It may have been moved, or this link might be incorrect.</p><a href="/" data-link class="primary-button">Back to your library ${icons.arrow}</a></div>${toast}`;
  }
}
function render() {
  const match = location.pathname.match(/^\/books\/([a-f\d-]{36})$/i);
  if (match) return detail(match[1]);
  document.title = 'Reading Room · Your personal bookshelf';
  home();
}
document.addEventListener('click', event => {
  const link = event.target.closest('a[data-link]');
  if (link && !event.ctrlKey && !event.metaKey && !event.shiftKey && !event.altKey && event.button === 0) {
    event.preventDefault(); navigate(link.getAttribute('href'));
  }
});
window.addEventListener('popstate', render);
try {
  books = await request('/api/books');
  render();
} catch (error) {
  app.innerHTML = `<div class="not-found"><h1>Couldn’t open your library.</h1><p>${escapeHTML(error.message)}</p><button class="primary-button" onclick="location.reload()">Try again</button></div>`;
}

