import { describe, it, expect } from 'vitest';
import { createApp } from './server.js';
import http from 'node:http';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

async function withServer(fn) {
  const dir = await mkdtemp(path.join(os.tmpdir(), 'reading-room-'));
  const dataFile = path.join(dir, 'books.json');
  const server = http.createServer(createApp({ dataFile }));
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const base = `http://127.0.0.1:${server.address().port}`;
  try { await fn(base, dataFile); }
  finally {
    await new Promise(resolve => server.close(resolve));
    await rm(dir, { recursive: true, force: true });
  }
}
const json = (method, data) => ({ method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });

describe('book app', () => {
  it('adds, reads, finishes, and persists books across app instances', async () => withServer(async (base, file) => {
    const empty = await fetch(`${base}/api/books`);
    expect(await empty.json()).toEqual([]);
    const created = await fetch(`${base}/api/books`, json('POST', { title: '  Dune ', author: ' Frank Herbert ', notes: 'A good read.' }));
    expect(created.status).toBe(201);
    const book = await created.json();
    expect(book).toMatchObject({ title: 'Dune', author: 'Frank Herbert', notes: 'A good read.', status: 'reading' });
    expect((await fetch(`${base}/api/books/${book.id}`)).status).toBe(200);
    expect((await fetch(`${base}/books/${book.id}`)).status).toBe(200);
    const finished = await fetch(`${base}/api/books/${book.id}`, json('PATCH', { status: 'finished' }));
    expect((await finished.json()).finishedAt).toBeTruthy();
    expect(JSON.parse(await readFile(file, 'utf8'))[0].status).toBe('finished');
    const second = http.createServer(createApp({ dataFile: file }));
    await new Promise(resolve => second.listen(0, '127.0.0.1', resolve));
    try {
      const saved = await fetch(`http://127.0.0.1:${second.address().port}/api/books/${book.id}`);
      expect((await saved.json()).status).toBe('finished');
    } finally { await new Promise(resolve => second.close(resolve)); }
  }));
  it('rejects invalid books and unknown ids', async () => withServer(async base => {
    expect((await fetch(`${base}/api/books`, json('POST', { title: '', author: 'Someone' }))).status).toBe(400);
    expect((await fetch(`${base}/api/books/00000000-0000-0000-0000-000000000000`)).status).toBe(404);
    expect((await fetch(`${base}/api/books`, { method: 'POST', body: '{' })).status).toBe(400);
  }));
  it('does not lose concurrent additions', async () => withServer(async base => {
    await Promise.all(Array.from({ length: 12 }, (_, i) => fetch(`${base}/api/books`, json('POST', { title: `Book ${i}`, author: 'Someone' }))));
    expect((await (await fetch(`${base}/api/books`)).json())).toHaveLength(12);
  }));
});

